note_models.css:
@font-face {
  font-family: "M Plus 2";
  src: url("_Mplus2-Regular.ttf");
}

html, body {
  height: 100%;
  margin: 0;
}

img {
  max-width: 60vw;
  max-height: 30vh;
  object-fit: contain;
  border-radius: 8px;
}

.img-src { position: relative; display: inline-block; }
.img-src:hover .tooltip, .img-src:active .tooltip { opacity: 1; }

.tooltip {
  position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
  white-space: nowrap; pointer-events: none;
  opacity: 0; 
}

.card {
  font-family: "M Plus 2", system-ui, sans-serif;
  color: #fff;
  box-sizing: border-box;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;

  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.katakana-front {
  font-size: clamp(1.8rem, 8vw, 3rem);
  font-weight: 700;
  white-space: nowrap;
}

.katakana-back {
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: 200;
  opacity: 0.7;
  margin-bottom: 0.75rem;
  white-space: nowrap;
  cursor: pointer;
  transition: 0.2s;
}

.katakana-back:hover {
  opacity: 1;
  color: #89b4fa;
}

.meaning {
  font-size: 1.85rem;
  font-weight: 550;
}

.origin, .notes {
  font-style: italic;
  opacity: 0.85;
}

.origin {
  font-size: 1.05rem;
  margin-bottom: 0.5rem;
}

.notes {
  font-size: 0.95rem;
  opacity: 0.7;
}
